          const score = wantsScore(chunks, anchorX, anchorY, plan.wants || [])
            + terrainFit
            - dist * 4
            - doorDist * 1.5
            + doorFacingScore(def, anchorX, anchorY, facingTarget)
            + rng() * 0.01;
